const strategyStateCases = [
  [false, null, 0, "waiting"],
  [false, false, 5, "waiting"],
  [true, null, 5, "waiting"],
  [true, true, 0, "warming"],
  [true, true, 5, "active"],
  [true, false, 0, "paused_empty"],
  [true, false, 5, "paused_snapshot"],
];
for (const [backendReady, adaptive, scoreCount, expected] of strategyStateCases) {
  assert.equal(
    strategyDecisionViewState(backendReady, adaptive, scoreCount),
    expected,
    `strategy decision state for ${backendReady}/${adaptive}/${scoreCount}`,
  );
}
console.log(`PASS strategy decision states: ${strategyStateCases.length} loading/live/paused cases`);

const failures = [];
for (const check of checks) {
  const passed = check.pattern.test(fs.readFileSync(check.file, "utf8"));
  console.log(`${passed ? "PASS" : "FAIL"} ${check.description} [${check.file}]`);
  if (!passed) failures.push(check.description);
}
if (failures.length) {
  console.error(`UX contract failed: ${failures.length}/${checks.length}`);
  process.exitCode = 1;
} else {
  console.log(`UX contract passed: ${checks.length} checks`);
}
